fn count_true(condition: &[bool]) -> usize {
    condition.iter().filter(|&&x| x).count()
}

fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    assert_eq!(condition.len(), arr.len(), "Condition and array must be of the same length");

    let result: Vec<f32> = condition.iter()
        .zip(arr.iter())
        .filter_map(|(&cond, &value)| if cond { Some(value) } else { None })
        .collect();

    result
}